import { test, expect } from '@playwright/test';

test.describe('Image Upload - Dimension Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display error when image dimensions are too small', async ({ page }) => {
    // Create a small test image (100x100 pixels - below minimum requirement)
    const smallImageBuffer = Buffer.from(
      '',
      'base64'
    );

    const fileInput = page.getByLabel(/upload.*image/i);
    await fileInput.setInputFiles({
      name: 'small-image.png',
      mimeType: 'image/png',
      buffer: smallImageBuffer,
    });

    const errorMessage = page.getByText(/image dimensions.*too small|minimum.*dimensions|width.*height.*required/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should show specific error message with minimum dimension requirements', async ({ page }) => {
    const smallImageBuffer = Buffer.from(
      '',
      'base64'
    );

    const fileInput = page.getByLabel(/upload.*image/i);
    await fileInput.setInputFiles({
      name: 'small-image.png',
      mimeType: 'image/png',
      buffer: smallImageBuffer,
    });

    const errorContainer = page.getByRole('alert');
    await expect(errorContainer).toBeVisible();

    const errorText = await errorContainer.textContent();
    expect(errorText).toMatch(/\d+x\d+|dimensions|pixels/i);
  });

  test('should clear error message when valid image is uploaded', async ({ page }) => {
    // First upload a small image to trigger error
    const smallImageBuffer = Buffer.from(
      '',
      'base64'
    );

    const fileInput = page.getByLabel(/upload.*image/i);
    await fileInput.setInputFiles({
      name: 'small-image.png',
      mimeType: 'image/png',
      buffer: smallImageBuffer,
    });

    const errorMessage = page.getByText(/image dimensions.*too small|minimum.*dimensions|width.*height.*required/i);
    await expect(errorMessage).toBeVisible();

    // Create a larger valid image (1000x1000 pixels)
    const validImageBuffer = Buffer.alloc(1000 * 1000 * 4);
    validImageBuffer.fill(0);

    await fileInput.setInputFiles({
      name: 'valid-image.png',
      mimeType: 'image/png',
      buffer: validImageBuffer,
    });

    await expect(errorMessage).not.toBeVisible();
  });
});
